INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (582, 1, '가장 바쁜 디스크', '`/tmp/iostat.log` 는 `iostat -x` 의 출력입니다. `%util` 은 디스크가 요청 처리에 바빴던 시간의 비율입니다. **`%util` 이 가장 높은 디스크 이름**을 `/tmp/busy.txt` 에 저장하세요.', '디스크 줄에서 마지막 열이 `%util` 입니다. 값이 큰 줄의 첫 칸을 보세요.', 'cat /tmp/iostat.log
grep ''^sd'' /tmp/iostat.log | sort -k8 -n -r | head -1 | awk ''{print $1}'' > /tmp/busy.txt
cat /tmp/busy.txt

# sda 가 99.8% 로 사실상 포화다. 포화된 디스크에서는 요청이 줄을 서서 지연(await)이 늘어난다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/busy.txt)\\" = sda ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "sda 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/busy.txt)\\" = sda ]"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 2, '지연이 큰 디스크', '`await` 는 요청 하나가 끝나기까지 걸린 평균 시간(ms)입니다. (이 샘플은 열을 줄인 것이며 최신 iostat 은 r_await·w_await 로 나눠 보여 줍니다.) 이 값이 **10ms 를 넘는 디스크**의 이름을 **한 줄에 하나씩, 이름순으로** `/tmp/slow.txt` 에 저장하세요.', '`await` 열의 위치를 헤더에서 확인하고 값이 기준을 넘는 줄의 첫 칸을 모으세요. 소수점이 있어 정수 비교가 아닌 방법이 필요합니다.', 'grep ''^sd'' /tmp/iostat.log | awk ''$6 > 10 {print $1}'' | sort > /tmp/slow.txt
cat /tmp/slow.txt

# HDD 에서 await 가 수십 ms 이면 병목이다. sda(45ms)와 sdc(14.5ms)가 해당한다. NVMe·SSD 는 보통 1ms 안팎이어야 정상이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/slow.txt | xargs)\\" = \\"sda sdc\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "sda, sdc 다", "cmd": ["sh", "-c", "[ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/slow.txt | xargs)\\" = \\"sda sdc\\" ]"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 3, 'CPU 가 디스크를 기다린 비율', '`/tmp/iostat.log` 맨 위 `avg-cpu` 줄에서 **`%iowait`**(CPU 가 디스크 I/O 완료를 기다리느라 놀고 있던 비율) 값을 읽어 `/tmp/iowait.txt` 에 저장하세요. (숫자만)', '맨 앞의 `avg-cpu:` 는 값 줄에 대응하는 칸이 없어 열 번호가 한 칸 어긋납니다. 열 이름의 순서를 세어 값 줄의 어느 칸인지 맞춰 보세요.', 'head -3 /tmp/iostat.log
sed -n ''2p'' /tmp/iostat.log | awk ''{print $4}'' > /tmp/iowait.txt
cat /tmp/iowait.txt

# iowait 가 높으면 CPU 는 한가한데 디스크를 기다리는 중이라 디스크가 병목이라는 신호다. 다만 iowait 자체는 CPU 를 쓰지 않는 대기 시간이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( awk ''{exit !($1+0==42.5)}'' /tmp/iowait.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "42.50 이다", "cmd": ["sh", "-c", "awk ''{exit !($1+0==42.5)}'' /tmp/iowait.txt"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 4, '블록된 프로세스 수', '`/tmp/vmstat.log` 는 `vmstat` 의 출력입니다. `b` 열은 **I/O 완료를 기다리느라 멈춰 있는(블록된) 프로세스 수**, `wa` 열은 CPU 의 iowait 비율입니다. 마지막 줄(가장 최근)의 `b` 값과 `wa` 값을 저장하세요. (숫자만)
- `/tmp/blocked.txt` : `b`
- `/tmp/wa.txt` : `wa`', '마지막 줄을 열 번호로 뽑으세요. 헤더의 두 번째 줄에서 열 이름의 순서를 확인하세요.', 'cat /tmp/vmstat.log
tail -1 /tmp/vmstat.log | awk ''{print $2}'' > /tmp/blocked.txt
tail -1 /tmp/vmstat.log | awk ''{print $16}'' > /tmp/wa.txt
cat /tmp/blocked.txt /tmp/wa.txt

# 처음 줄은 부팅 이후 평균이라 현재를 반영하지 않는다. 뒤 줄에서 b 가 6~7, wa 가 50% 넘게 올라 디스크 쓰기(bo 약 10000)가 병목임을 보여 준다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/blocked.txt)\\" = 7 ] ) && ( [ \\"$(cat /tmp/wa.txt)\\" = 55 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "b 가 7 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/blocked.txt)\\" = 7 ]"]}, {"label": "wa 가 55 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/wa.txt)\\" = 55 ]"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 5, 'fio 의 IOPS 읽기', '`/tmp/fio.log` 는 `fio` 로 디스크를 시험한 결과입니다. 첫 번째 작업 **`randread`**(무작위 읽기)의 **IOPS**(초당 입출력 횟수) 값을 숫자만 `/tmp/iops.txt` 에 저장하세요.', '작업 이름 줄 아래 `read:` 줄에 `IOPS=` 가 있습니다. 첫 작업만 필요합니다.', 'cat /tmp/fio.log
grep -m1 -o ''IOPS=[0-9]*'' /tmp/fio.log | cut -d= -f2 > /tmp/iops.txt
cat /tmp/iops.txt

# 무작위 읽기는 IOPS(8204)가 중요하고 순차 읽기는 처리량(550MiB/s)이 중요하다. 작업 특성에 따라 봐야 할 지표가 다르다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/iops.txt)\\" = 8204 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "8204 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/iops.txt)\\" = 8204 ]"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 6, '순차와 무작위 처리량 비교', '`/tmp/fio.log` 에서 **`seqread`**(순차 읽기)의 처리량(`BW=` 뒤의 `MiB/s` 숫자)과 **`randread`** 의 처리량의 **비율**(순차 ÷ 무작위, 소수점 이하 버림 정수)을 `/tmp/ratio.txt` 에 저장하세요. 같은 디스크라도 접근 방식에 따라 처리량이 얼마나 다른지 확인하는 것입니다.', '두 `BW=` 값을 각각 뽑아 정수로 나누세요. 단위(`MiB/s`)와 소수점이 붙어 있어 잘라 내야 합니다. 쉘 산술은 정수만 다룹니다.', 'grep -o ''BW=[0-9.]*MiB/s'' /tmp/fio.log
R=$(grep -o ''BW=[0-9.]*MiB/s'' /tmp/fio.log | head -1 | cut -d= -f2 | cut -d. -f1 | tr -d ''MiB/s'')
S=$(grep -o ''BW=[0-9.]*MiB/s'' /tmp/fio.log | tail -1 | cut -d= -f2 | cut -d. -f1 | tr -d ''MiB/s'')
echo $((S / R)) > /tmp/ratio.txt
cat /tmp/ratio.txt

# 550 ÷ 32 = 17 배. 같은 디스크라도 작은 무작위 I/O 는 처리량이 크게 떨어진다. 용도에 맞는 지표와 시험 방식을 골라야 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/iostat.log <<''EOF''\\navg-cpu:  %user   %nice %system %iowait  %steal   %idle\\n           8.10    0.00    3.40   42.50    0.00   46.00\\n\\nDevice            r/s     w/s    rkB/s    wkB/s   await  aqu-sz  %util\\nsda               2.00  150.00     8.00  1200.00   45.20    6.80  99.80\\nsdb               5.00    3.00    40.00    24.00    0.80    0.01   1.20\\nsdc              90.00   10.00  4500.00   300.00   14.50    1.40  70.00\\n# (열을 줄인 샘플입니다. 최신 iostat -x 는 await 가 r_await, w_await 로 나뉘어 나옵니다)\\nEOF\\ncat > /tmp/vmstat.log <<''EOF''\\nprocs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\\n 1  0      0 812340  52000 640000    0    0    20    30  150  300  5  2 92  1  0\\n 1  6      0 810120  52100 641000    0    0    10  9800  400  900  4  3 40 53  0\\n 2  7      0 809900  52100 641500    0    0     5 10200  420  950  4  3 38 55  0\\nEOF\\ncat > /tmp/fio.log <<''EOF''\\nrandread: (groupid=0, jobs=1): err= 0: pid=1234\\n  read: IOPS=8204, BW=32.0MiB/s (33.6MB/s)(1920MiB/60001msec)\\n    clat (usec): min=60, max=18520, avg=121.40, stdev=88.12\\nseqread: (groupid=1, jobs=1): err= 0: pid=1235\\n  read: IOPS=1100, BW=550MiB/s (577MB/s)(32.8GiB/61000msec)\\n    clat (usec): min=300, max=9200, avg=880.20, stdev=210.40\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/ratio.txt)\\" = 17 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "17 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ratio.txt)\\" = 17 ]"]}]', '[{"title": "iostat 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/iostat.1.html"}, {"title": "fio 문서", "url": "https://fio.readthedocs.io/en/latest/"}]'),
  (582, 7, 'iowait 가 높다는 것', '서버가 느린데 `top` 의 `wa`(%iowait) 가 50% 를 넘고 CPU 사용률(`us`+`sy`)은 낮습니다. 가장 알맞은 해석은?', 'CPU 가 바쁘지 않은데 느리다면 무엇을 기다리는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["CPU 성능이 부족해 연산이 느리다", "메모리가 모자라 프로세스가 강제 종료되고 있다", "디스크 I/O 대기가 길어 디스크가 병목이다", "네트워크 대역폭이 모자라 패킷이 유실되고 있다"]', 2, '%iowait 는 CPU 가 할 일이 없는데 디스크 I/O 를 기다리며 쉬는 시간의 비율입니다. 높으면 디스크(또는 네트워크 스토리지)가 병목일 가능성이 큽니다. iostat -x 로 어느 디스크가 바쁜지, 프로세스 단위로 누가 I/O 를 일으키는지 이어서 확인합니다.', NULL, NULL, NULL, NULL),
  (582, 8, '%util 100 의 의미', 'NVMe 디스크의 `iostat -x` 에서 `%util` 이 100 인데 `await` 는 0.3ms 로 매우 낮고 응용 지연도 없습니다. 이 현상에 대한 설명으로 가장 알맞은 것은?', '%util 이 정확히 무엇의 비율인지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["%util 100 이면 어떤 디스크든 항상 한계에 도달한 것이다", "%util 은 요청이 있던 시간의 비율이라 병렬 장치는 100 이어도 여유가 있다", "%util 은 디스크 사용 용량의 비율이다", "await 가 낮아서 %util 은 의미가 없는 지표다"]', 1, '%util 은 장치에 요청이 하나라도 있던 시간의 비율일 뿐 동시에 몇 개를 처리했는지는 반영하지 않습니다. HDD 같은 직렬 장치에서는 100% 가 포화이지만, 병렬로 많이 처리하는 NVMe 는 100% 여도 여유가 있을 수 있어 await·aqu-sz 와 함께 봐야 합니다. 용량 사용률은 df 가 보여 줍니다.', NULL, NULL, NULL, NULL),
  (582, 9, '확장 통계 옵션', '`iostat` 에서 `await`, `aqu-sz`, `%util` 같은 **확장 통계**를 보려면 어떤 옵션을 줘야 할까요? 빈칸을 채우세요. (1초 간격으로 5번 출력)', '`iostat` 의 기본 출력에는 지연 같은 세부 지표가 없습니다. 더 자세한 통계를 켜는 옵션입니다.', NULL, NULL, '[]', 'fill', '["x", "c", "d", "k"]', NULL, '`-x` 는 확장 통계(await·aqu-sz·%util 등)를 보여 줍니다. `-c` 는 CPU 통계만, `-d` 는 디스크 통계만, `-k` 는 KB 단위 표시입니다. 첫 번째 줄은 부팅 이후 평균이니 두 번째 줄부터 현재를 봅니다.', '[0]', 'iostat -{0} 1 5', NULL, NULL),
  (582, 10, '서버가 느릴 때 디스크 병목 확인 순서', '서버가 느립니다. 디스크가 원인인지 확인하고 대응하려고 합니다. 큰 그림에서 작은 단위로 좁혀 가는 순서로 놓으세요.', '각 도구가 무엇의 단위(시스템·디스크·프로세스)를 보여 주는지 생각해 보세요.', NULL, NULL, '[]', 'order', '["어느 프로세스가 I/O 를 일으키는지 찾는다(`iotop`·`pidstat -d`)", "`iostat -x` 로 어느 디스크가 바쁜지(`%util`·`await`) 본다", "원인 작업을 조정하거나 디스크 증설·분산을 검토한다", "`top`·`vmstat` 으로 `%iowait` 와 블록된 프로세스가 많은지 본다"]', NULL, '먼저 iowait 같은 전체 신호로 디스크가 병목인지 확인하고, iostat 으로 어느 디스크인지 좁힌 뒤, 프로세스 단위로 원인을 찾고, 마지막에 작업 조정이나 증설 같은 조치를 합니다.', '[3, 1, 0, 2]', NULL, NULL, NULL);
